{
  "name": "pairwise_preference_loss",
  "intuition": "This loss encourages preference for higher quality samples by comparing their log probabilities, scaled by a cost gap measure which indicates the quality difference. Using logsigmoid on the difference of log probs emphasizes the preference signal smoothly and stably, promoting higher preference scores for better samples. It aligns with the goal of RL4CO to optimize for preferences in a pairwise manner, guiding the model toward better solutions.",
  "pseudocode": "loss = -mean(logsigmoid(log_prob_w - log_prob_l + alpha * cost_gap))",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "comparison",
    "link_family": "logistic",
    "agg_family": "mean",
    "constraint_family": "pairwise",
    "other_hparams": "alpha"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    cost_gap = batch.get(\"cost_gap\", ops.zeros_like(log_prob_w))\n    preference_diff = log_prob_w - log_prob_l + alpha * cost_gap\n    loss = -ops.mean(ops.logsigmoid(preference_diff))\n    return loss"
}

{
  "name": "loss_pairwise_rankgap_tanh_advantage",
  "intuition": "Use a rank-gap based loss that directly penalizes the discrepancy in ranking scores between winning and losing sequences, modulated by their advantage signals, with a smooth tanh link to encourage gradual gradients.",
  "pseudocode": "rank_gap = rank_gap(lpw, lpl)\nadvantage_diff = advantage_w - advantage_l\nscaled_gap = alpha * rank_gap * advantage_diff\nloss = mean(tanh(scaled_gap)) weighted by weight",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["rank_gap", "tanh", "mean", "mul", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    gap = ops.rank_gap(lpw, lpl)\n    adv_diff = ops.sub(adv_w, adv_l)\n    scaled = ops.mul(ops.mul(alpha, gap), adv_diff)\n    loss = ops.tanh(scaled)\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return loss.mean()"
}

{
  "name": "loss_contrastive_margin_tanh_costgap_repaired_v3",
  "intuition": "Contrastive pairwise loss with bounded tanh margin on cost gap, enforcing margin constraint with relu and stable weighted mean, preserving original advantage-based margin intent.",
  "pseudocode": "cost_gap = cost_b - cost_a\nmargin = tanh(beta * cost_gap)\nloss = relu(margin_const - margin)\nweighted_loss = weight * loss\nfinal_loss = mean(weighted_loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_contrastive",
    "signal_family": "cost_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "relu_margin",
    "other_hparams": "beta, margin_const"
  },
  "operators_used": ["tanh", "relu", "sub", "mul", "mean", "logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    zeros = lpw.new_zeros(lpw.shape)\n    cost_gap = batch.get('cost_gap', batch.get('cost_b', zeros) - batch.get('cost_a', zeros))\n    beta = float(extra.get('beta', 1.0))\n    margin_const = float(extra.get('margin_const', 0.5))\n    margin_raw = beta * cost_gap\n    margin = ops.tanh(margin_raw)\n    loss = ops.relu(margin_const - margin)\n    weighted_loss = loss * weight\n    grad_term = ops.logsigmoid(lpw - lpl)\n    combined_loss = weighted_loss + 1e-6 * (-grad_term)\n    return combined_loss.mean()"
}

