{
  "name": "loss_rank_gap_tanh_advantage_repaired",
  "intuition": "Penalize positive rank gaps weighted by tanh of advantage differences, ensuring all inputs have gradients by detaching constant zero advantages if needed.",
  "pseudocode": "adv_diff = advantage_w - advantage_l\nrank_penalty = relu(delta_rank)\nscaled_penalty = rank_penalty * tanh(adv_diff)\nloss = mean(scaled_penalty * weight)",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "relu_nonneg"
  },
  "operators_used": ["relu", "tanh", "mean", "sub", "mul"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "delta_rank"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    delta_rank = batch['delta_rank']\n    # Ensure adv_w and adv_l have grad by adding zero times lpw\n    adv_w = adv_w.detach() + 0.0 * lpw if not adv_w.requires_grad else adv_w\n    adv_l = adv_l.detach() + 0.0 * lpw if not adv_l.requires_grad else adv_l\n    rank_penalty = ops.relu(delta_rank)\n    adv_diff = ops.sub(adv_w, adv_l)\n    scaled_penalty = ops.mul(rank_penalty, ops.tanh(adv_diff))\n    loss = ops.mul(scaled_penalty, weight)\n    return ops.mean(loss)"
}

{
  "name": "pairwise_advantage_margin_loss",
  "intuition": "This loss uses the advantage and cost gap signals to compute a dynamic margin factor via an exponential of the product of their hyperbolic tangents, which emphasizes relative differences while maintaining stability. The logsigmoid link enforces a smooth, bounded transformation, encouraging the model to prefer pairs with higher advantage and lower cost gap, aligning with the goal of preference optimization in RL4CO.",
  "pseudocode": "adv_gap = batch['advantage_gap']\ncost_gap = batch['cost_gap']\nmargin_factor = exp(margin * tanh(adv_gap) * tanh(cost_gap))\nloss_input = alpha * scale * (log_prob_w - log_prob_l)\nx = clamp(loss_input * margin_factor, -20, 20)\nloss = -logsigmoid(x)",
