    "paradigm_family": "pairwise_margin",
    "signal_family": "advantage_cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "mean",
    "constraint_family": "normalization",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "clamp", "exp", "tanh", "sum", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_gap = batch['advantage_gap']\n    cost_gap = batch['cost_gap']\n    alpha = float(extra.get('alpha', 1.0))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n    margin = float(extra.get('hyperparams', {}).get('margin', 0.1))\n    margin_factor = ops.exp(margin * ops.tanh(adv_gap) * ops.tanh(cost_gap))\n    loss_input = alpha * scale * (lpw - lpl)\n    x = loss_input * margin_factor\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    return loss if weight is None else (loss * weight).sum() / ops.clamp(weight.sum(), 1e-6, float('inf'))"
}

