{
  "name": "loss_rank_gap_weighted_tanh_margin_repaired",
  "intuition": "Removed unsupported 'rank_gap' key from expects and replaced it with 'advantage_gap' which is a valid advantage signal reflecting preference strength. Replaced direct rank_gap with advantage_gap as a smooth proxy weighted by tanh margin computed from scaled difference of log probabilities. This ensures numerical stability and uses only supported keys. The margin is computed from (log_prob_w - log_prob_l) scaled and bounded by tanh to keep margins stable. The loss penalizes negative margins with ReLU, weighted by advantage_gap, and aggregated by weighted mean if weight provided. This stabilizes and simplifies the original design while respecting all constraints.",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "advantage_gap"
    ],
    "returns": "scalar"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_gap = batch['advantage_gap']\n    scale = float(extra.get('scale', extra.get('hyperparams', {}).get('scale', 2.0)))\n    margin = ops.tanh(scale * (lpw - lpl))\n    loss_per_pair = ops.relu(-margin) * adv_gap\n    if weight is not None:\n        loss_per_pair = loss_per_pair * weight\n        norm = ops.clamp(weight.sum(), 1e-6, float('inf'))\n        loss_val = loss_per_pair.sum() / norm\n    else:\n        loss_val = loss_per_pair.mean()\n    return loss_val"
}

{
  "name": "loss_rank_gap_relaxed_hinge_tanh_weighted",
  "intuition": "Shift from margin-based logistic losses to a hinge-like relaxed ranking loss using rank gap as the signal. The loss penalizes negative margins with a smooth tanh-based relaxation to avoid harsh zero-gradient regions, and aggregates losses weighted by importance.",
  "pseudocode": "rank_gap = batch['delta_rank']\nmargin = alpha * scale * (log_prob_w - log_prob_l)\nrelaxed_margin = margin * tanh(rank_gap)\nloss = relu(1 - relaxed_margin)\nweighted_loss = loss * weight\nreturn weighted_loss.mean()",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "rank_gap",
    "link_family": "relu_tanh_relaxation",
    "agg_family": "mean_weighted",
    "constraint_family": "none"
  },
  "operators_used": ["relu", "tanh", "mul", "sub", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "delta_rank"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    rank_gap = batch['delta_rank']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n    margin = alpha * scale * (lpw - lpl)\n    relaxed_margin = margin * ops.tanh(rank_gap)\n    relu_input = ops.relu(1.0 - relaxed_margin)\n    loss = relu_input\n    weighted_loss = loss * weight\n    return weighted_loss.mean()"
}

