  "code": "def generated_loss(batch, model_output, extra):
    eps = 1e-8
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch['weight']
    adv_gap = batch['advantage_gap']
    cost_gap = batch['cost_gap']

    alpha = float(extra.get('alpha', 1.0))
    hyper = extra.get('hyperparams', {})
    scale = float(hyper.get('scale', 1.9496803035382082))
    margin = float(hyper.get('margin', 0.15))
    reg_coef = float(hyper.get('reg_coef', 0.01))
    scale_margin = float(hyper.get('scale_margin', 0.5))
    clip_val = float(hyper.get('clip_val', 0.3))

    margin_raw = margin * ops.tanh(adv_gap) * ops.tanh(cost_gap)
    idxs = ops.arange(margin_raw.numel(), device=margin_raw.device, dtype=margin_raw.dtype)
    noise = 0.005 * ops.sin(idxs * 3.14159 / 5)
    margin_raw = margin_raw + noise

    max_margin_raw = margin_raw.max()
    margin_exp_unnorm = ops.exp(margin_raw - max_margin_raw)
    margin_exp_sum = margin_exp_unnorm.sum().clamp(min=eps)
    margin_exp_softmax = margin_exp_unnorm / margin_exp_sum
    n = margin_exp_softmax.numel()

    margin_factor_raw = 1.0 + scale_margin * (margin_exp_softmax - 1.0 / n)
    margin_factor = ops.clamp(margin_factor_raw, 1.0 - clip_val, 1.0 + clip_val)

    loss_input = alpha * scale * (lpw - lpl)
    x = ops.clamp(loss_input * margin_factor, -20.0, 20.0)
    loss = -ops.logsigmoid(x)

    weighted_loss = loss * weight
    norm = weight.sum().clamp(min=eps)
    loss_val = weighted_loss.sum() / norm

    hinge_reg = reg_coef * ops.clamp(ops.abs(margin_factor - 1.0) - 0.1, 0.0, None).pow(2).mean()

    return loss_val + hinge_reg

# Helper function for arange since ops.* does not have arange
import torch
class ops:
    @staticmethod
    def logsigmoid(x):
        return torch.nn.functional.logsigmoid(x)
    @staticmethod
    def clamp(x, min_val=None, max_val=None):
        return x.clamp(min=min_val, max=max_val)
    @staticmethod
    def exp(x):
        return x.exp()
    @staticmethod
    def tanh(x):
        return x.tanh()
    @staticmethod
    def sum(x):
        return x.sum()
    @staticmethod
    def abs(x):
        return x.abs()
    @staticmethod
    def pow(x, p):
        return x.pow(p)
    @staticmethod
    def sin(x):
        return x.sin()
    @staticmethod
    def arange(*args, **kwargs):
        return torch.arange(*args, **kwargs)
