{
  "name": "sampled_pairs_global_topk_fixed",
  "intuition": "Selects up to max_pairs global positive preference pairs by vectorized indexing of objective gaps, returning a valid PrefBatch with correct batch, winner and loser indices without imports or loops.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']  # (B, N)
    gap = objective[:, None, :] - objective[:, :, None]  # (B, N, N)
    mask = gap > 0
    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)
    scores = gap[b_idx, winner_idx, loser_idx]
    max_pairs_total = int(extra.get('max_pairs', 415))
