            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={'builder': 'sampled_pairs_global_topk_fixed', 'max_pairs_total': max_pairs_total}
        )
    topk_indices = scores.topk(k=k, largest=True, sorted=False).indices
    b_idx = b_idx[topk_indices]
    winner_idx = winner_idx[topk_indices]
    loser_idx = loser_idx[topk_indices]
    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, winner_idx, loser_idx),
        weight=None,
        meta={'builder': 'sampled_pairs_global_topk_fixed', 'max_pairs_total': max_pairs_total}
    )"
