{
  "name": "builder_topk_per_anchor_budget_002",
  "intuition": "select top-k pairs per anchor instance to enforce per-instance budget cap",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "topk_per_anchor",
    "weight_family": "uniform_none",
    "constraint_family": "clamp_tiezone"
  },
  "operators_used": [
    "all_pairs",
    "topk",
    "sub",
    "abs",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    objective = feature_cache['objective']\n    margin = float(extra.get('clamp_epsilon', 1e-4))\n    topk = int(extra.get('topk_per_anchor', 5))\n    diff = objective[:, :, None] - objective[:, None, :]\n    mask = diff < -margin\n    b_size, n_items = objective.shape\n    weights = torch.zeros_like(diff, dtype=torch.float32)\n    weights[mask] = diff[mask].abs()\n    topk_vals, topk_idx = torch.topk(weights, k=topk, dim=2)\n    topk_mask = torch.zeros_like(weights, dtype=torch.bool)\n    batch_indices = torch.arange(b_size, device=objective.device)[:, None, None]\n    anchor_indices = torch.arange(n_items, device=objective.device)[None, :, None]\n    topk_mask[batch_indices, anchor_indices, topk_idx] = True\n    valid_mask = mask & topk_mask\n    b_idx, winner_idx, loser_idx = valid_mask.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'topk_per_anchor_budget'})"
}

