  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    delta_rank = batch['delta_rank']\n    rank_penalty = ops.relu(delta_rank)\n    adv_diff = ops.sub(adv_w, adv_l)\n    scaled_penalty = ops.mul(rank_penalty, ops.tanh(adv_diff))\n    log_prob_diff = ops.sub(lpw, lpl)\n    loss_per_pair = ops.mul(ops.neg(ops.logsigmoid(log_prob_diff)), scaled_penalty)\n    loss_per_pair = ops.mul(loss_per_pair, weight)\n    return ops.mean(loss_per_pair)"
}

